arguments.new:
// ---- shaft (external, pot D-shaft) ----
module shaft() {
    intersection() {
        cylinder(d=shaft_d, h=shaft_len, $fn=64);
        translate([-10,-10,0]) cube([(shaft_flat+10), 20, shaft_len]);
    }
}

// ---- set screw (external, M3 grub: 3 mm dia, tip on the shaft flat) ----
screw_d_out = 3.0;
screw_tip_x = 1.5;      // tip face coplanar with the shaft flat
screw_tail_x = 7.5;     // tail buried in the nut, inside the pocket
module screw() {
    translate([screw_tip_x, 0, screw_z])
        rotate([0,90,0])
            cylinder(d=screw_d_out, h=screw_tail_x-screw_tip_x, $fn=24);
}

// ---- assembly placement ----
module assembly() {
    // knob elevated so shaft bottom sits at z=0
    instance("knob", "knob") translate([0,0,assy_base]) knob();
    // shaft fully inserted: top flush with bore ceiling (assy_base+15=25)
    instance("shaft", "external") shaft();
    // nut in pocket, axis along X, inner face at nut_inner
    instance("nut", "standard:m3_nut") translate([nut_inner, 0, assy_base+screw_z]) rotate([0,90,0]) rotate([0,0,30]) m3_nut();
    // set screw through the nut, tip touching the shaft flat
    instance("screw", "external") translate([0, 0, assy_base]) screw();
}

